-- SNAPSHOT PRE-IMPORT JULIO
-- READ-ONLY: Estado actual de BD antes de ejecutar importer
-- Retorna UN SOLO RESULT SET con 10 métricas

SELECT
  (SELECT COUNT(*) FROM mp_financial_movement) as fm_total,

  (SELECT COUNT(*) FROM ledger_entry) as le_total,

  (SELECT COUNT(*) FROM mp_financial_movement WHERE needs_review = TRUE) as needs_review_total,

  (SELECT COUNT(*) FROM mp_source_record WHERE source_type = 'liberaciones') as liberaciones_sr_total,

  (SELECT COUNT(*) FROM mp_movement_source_link l
   WHERE EXISTS (SELECT 1 FROM mp_source_record sr
                 WHERE sr.id = l.source_record_id
                   AND sr.source_type = 'liberaciones')) as liberaciones_links_total,

  (SELECT COUNT(DISTINCT fm.id)
   FROM mp_financial_movement fm
   WHERE fm.id IN (
     SELECT l.financial_movement_id
     FROM mp_movement_source_link l
     WHERE l.source_record_id IN (
       SELECT id FROM mp_source_record WHERE source_type = 'liberaciones'
     )
   )) as liberaciones_fm_total,

  (SELECT COALESCE(SUM(balance_impact), 0)::NUMERIC(15,2)
   FROM ledger_entry
   WHERE account_id = 1054315166
     AND occurred_at >= '2026-07-01'::timestamp
     AND occurred_at < '2026-08-01'::timestamp) as ledger_julio_actual,

  (SELECT COUNT(DISTINCT sr.source_external_id)
   FROM mp_source_record sr
   WHERE sr.source_type = 'report'
     AND sr.source_external_id IN (
       '166290946951', '167135542004', '166292379013', '166294051443',
